package com.example.takura.quotations.application;

import com.example.takura.identity.application.PermissionService;
import com.example.takura.identity.domain.StaffPrincipal;
import com.example.takura.media.application.ObjectStoragePort;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class QuoteService {
    private final JdbcTemplate jdbc; private final PermissionService permissions; private final ObjectStoragePort storage;
    private final QuoteSecretProtector secrets; private final ObjectMapper json; private final Clock clock; private final ZoneId zone;
    private final String configurationVersion; private final SecureRandom random = new SecureRandom();
    public QuoteService(JdbcTemplate jdbc,PermissionService permissions,ObjectStoragePort storage,QuoteSecretProtector secrets,ObjectMapper json,Clock clock,
        @Value("${takura.quote.timezone:Africa/Johannesburg}")String zone,
        @Value("${takura.quote.configuration-version:demo-quote-v1}")String configurationVersion){this.jdbc=jdbc;this.permissions=permissions;this.storage=storage;this.secrets=secrets;this.json=json;this.clock=clock;this.zone=ZoneId.of(zone);this.configurationVersion=configurationVersion;}

    @Transactional public QuoteView create(StaffPrincipal actor,UUID enquiry,CreateDraft request){require(actor,"quote:draft");scope(actor,enquiry);validateDraft(request);
        jdbc.query("SELECT pg_advisory_xact_lock(hashtext(?))",rs->{rs.next();return null;},"quote:"+enquiry); UUID group=request.groupId();
        if(group==null){group=UUID.randomUUID();jdbc.update("INSERT INTO takura.quote_group(id,enquiry_id,quote_number,created_by,created_at) VALUES(?,?,?,?,?)",group,enquiry,nextNumber(),actor.identityId(),now());}
        else if(!exists("SELECT EXISTS(SELECT 1 FROM takura.quote_group WHERE id=? AND enquiry_id=?)",group,enquiry))throw notFound();
        int revision=Optional.ofNullable(jdbc.queryForObject("SELECT COALESCE(max(revision_number),0)+1 FROM takura.quote_revision WHERE quote_group_id=?",Integer.class,group)).orElse(1);
        var pdf=pdf(actor,request.pdfAttachmentId(),enquiry);String digest=digest(pdf.checksum(),request);UUID id=UUID.randomUUID();Instant expiry=ZonedDateTime.of(clock.instant().atZone(zone).toLocalDate().plusDays(14),LocalTime.of(17,0),zone).toInstant();
        jdbc.update("INSERT INTO takura.quote_revision(id,quote_group_id,revision_number,state,pdf_attachment_id,pdf_object_version,pdf_checksum_sha256,amount,currency,tax_mode,scope_summary,material_snapshot,commercial_terms_snapshot,review_checklist,content_digest,configuration_version,expires_at,created_by,revision) VALUES(?,?,?,'DRAFT',?,?,?,?,?,?,?,?::jsonb,?::jsonb,?::jsonb,?,?,?,?,0)",id,group,revision,request.pdfAttachmentId(),pdf.version(),pdf.checksum(),request.amount(),upper(request.currency()),request.taxMode(),required(request.scopeSummary(),5000),write(request.materialSnapshot()),write(request.commercialTerms()),write(request.reviewChecklist()),digest,configurationVersion,Timestamp.from(expiry),actor.identityId());
        audit(actor,enquiry,"QUOTE_DRAFT_CREATED",Map.of("quote_revision_id",id,"revision",revision));return get(actor,id);}

    @Transactional public QuoteView edit(StaffPrincipal actor,UUID id,long expected,CreateDraft request){require(actor,"quote:draft");var row=lock(actor,id,expected);if(!Set.of("DRAFT","AWAITING_APPROVAL","APPROVED").contains(row.state()))throw conflict("QUOTE_IMMUTABLE","Issued or closed revisions are immutable.");validateDraft(request);var pdf=pdf(actor,request.pdfAttachmentId(),row.enquiry());String digest=digest(pdf.checksum(),request);
        jdbc.update("UPDATE takura.quote_revision SET state='DRAFT',pdf_attachment_id=?,pdf_object_version=?,pdf_checksum_sha256=?,amount=?,currency=?,tax_mode=?,scope_summary=?,material_snapshot=?::jsonb,commercial_terms_snapshot=?::jsonb,review_checklist=?::jsonb,content_digest=?,submitted_at=NULL,approved_by=NULL,approved_at=NULL,approval_digest=NULL,revision=revision+1 WHERE id=?",request.pdfAttachmentId(),pdf.version(),pdf.checksum(),request.amount(),upper(request.currency()),request.taxMode(),required(request.scopeSummary(),5000),write(request.materialSnapshot()),write(request.commercialTerms()),write(request.reviewChecklist()),digest,id);audit(actor,row.enquiry(),"QUOTE_EDITED_APPROVAL_INVALIDATED",Map.of("quote_revision_id",id));return get(actor,id);}

    @Transactional public QuoteView submit(StaffPrincipal actor,UUID id,long expected){require(actor,"quote:draft");var row=lock(actor,id,expected);if(!"DRAFT".equals(row.state()))throw conflict("STATE_CONFLICT","Only a draft can be submitted.");ensureComplete(id);jdbc.update("UPDATE takura.quote_revision SET state='AWAITING_APPROVAL',submitted_at=?,revision=revision+1 WHERE id=?",now(),id);audit(actor,row.enquiry(),"QUOTE_SUBMITTED",Map.of("quote_revision_id",id));return get(actor,id);}
    @Transactional public QuoteView approve(StaffPrincipal actor,UUID id,long expected){require(actor,"quote:approve");var row=lock(actor,id,expected);if(!"AWAITING_APPROVAL".equals(row.state()))throw conflict("STATE_CONFLICT","Only a submitted revision can be approved.");if(actor.identityId().equals(row.createdBy()))throw conflict("SELF_APPROVAL_FORBIDDEN","The quote drafter cannot approve this revision.");String digest=jdbc.queryForObject("SELECT content_digest FROM takura.quote_revision WHERE id=?",String.class,id);jdbc.update("UPDATE takura.quote_revision SET state='APPROVED',approved_by=?,approved_at=?,approval_digest=?,revision=revision+1 WHERE id=?",actor.identityId(),now(),digest,id);audit(actor,row.enquiry(),"QUOTE_APPROVED",Map.of("quote_revision_id",id));return get(actor,id);}

    @Transactional public IssueResult issue(StaffPrincipal actor,UUID id,long expected,String key){require(actor,"quote:issue");if(key==null||key.isBlank()||key.length()>120)throw bad("IDEMPOTENCY_KEY_REQUIRED","A valid Idempotency-Key is required.");var command=jdbc.query("SELECT quote_revision_id FROM takura.quote_issue_command WHERE idempotency_key=?",(rs,n)->(UUID)rs.getObject(1),key);if(!command.isEmpty()&&!command.getFirst().equals(id))throw conflict("IDEMPOTENCY_CONFLICT","The issue key belongs to another revision.");var prior=jdbc.query("SELECT s.encrypted_token,s.nonce,r.expires_at,s.destroyed_at FROM takura.quote_issue_command c JOIN takura.quote_delivery_secret s ON s.quote_revision_id=c.quote_revision_id JOIN takura.quote_revision r ON r.id=c.quote_revision_id WHERE c.idempotency_key=? AND c.quote_revision_id=?",(rs,n)->new Object[]{rs.getBytes(1),rs.getBytes(2),rs.getTimestamp(3).toInstant(),rs.getTimestamp(4)},key,id);if(!prior.isEmpty()){String recovered=prior.getFirst()[3]==null?secrets.unprotect((byte[])prior.getFirst()[0],(byte[])prior.getFirst()[1]):null;return issueResult(id,recovered,(Instant)prior.getFirst()[2]);}
        var row=lock(actor,id,expected);if(!"APPROVED".equals(row.state()))throw conflict("QUOTE_NOT_APPROVED","Only the exact approved revision can issue.");ensureComplete(id);var approval=jdbc.queryForMap("SELECT content_digest,approval_digest,expires_at FROM takura.quote_revision WHERE id=?",id);if(!Objects.equals(approval.get("content_digest"),approval.get("approval_digest")))throw conflict("APPROVAL_INVALIDATED","The approved content changed.");Instant expiry=((Timestamp)approval.get("expires_at")).toInstant();if(!expiry.isAfter(clock.instant()))throw conflict("QUOTE_EXPIRED","The quote expiry is not in the future.");var contact=jdbc.queryForMap("SELECT email,phone FROM takura.enquiry WHERE id=?",row.enquiry());if(contact.get("email")==null&&contact.get("phone")==null)throw conflict("CONTACT_ROUTE_REQUIRED","A usable delivery route is required.");
        String token=token(),hash=sha(token);UUID grant=UUID.randomUUID(),secret=UUID.randomUUID();var protectedToken=secrets.protect(token);jdbc.update("UPDATE takura.quote_revision SET state='SUPERSEDED',superseded_by=?,revision=revision+1 WHERE quote_group_id=? AND state='ISSUED'",id,row.group());jdbc.update("UPDATE takura.customer_quote_grant SET state='SUPERSEDED',revoked_at=? WHERE quote_revision_id IN (SELECT id FROM takura.quote_revision WHERE quote_group_id=? AND state='SUPERSEDED') AND state='ACTIVE'",now(),row.group());
        jdbc.update("UPDATE takura.quote_revision SET state='ISSUED',issued_by=?,issued_at=?,dispatch_state='PENDING',revision=revision+1 WHERE id=?",actor.identityId(),now(),id);jdbc.update("INSERT INTO takura.customer_quote_grant(id,quote_revision_id,token_hash,state,expires_at,created_at) VALUES(?,?,?,'ACTIVE',?,?)",grant,id,hash,Timestamp.from(expiry),now());jdbc.update("INSERT INTO takura.quote_delivery_secret(id,quote_revision_id,encrypted_token,nonce,expires_at) VALUES(?,?,?,?,?)",secret,id,protectedToken.ciphertext(),protectedToken.nonce(),Timestamp.from(expiry));jdbc.update("INSERT INTO takura.quote_issue_command(idempotency_key,quote_revision_id,issued_at) VALUES(?,?,?)",key,id,now());if(contact.get("email")!=null)jdbc.update("INSERT INTO takura.notification_outbox(id,event_type,aggregate_id,semantic_key,payload,next_attempt_at,originating_correlation_id,originating_trace_id,created_at) VALUES(?,'QUOTE_ISSUE',?,?,jsonb_build_object('template','quote-issue','delivery_secret_id',?::text),?,?,?,?) ON CONFLICT(semantic_key) DO NOTHING",UUID.randomUUID(),row.enquiry(),"quote-issue:"+id,secret,now(),org.slf4j.MDC.get("correlation_id"),org.slf4j.MDC.get("traceId"),now());jdbc.update("UPDATE takura.enquiry SET quote_issued_evidence=?,revision=revision+1 WHERE id=?",id.toString(),row.enquiry());audit(actor,row.enquiry(),"QUOTE_ISSUED",Map.of("quote_revision_id",id));return issueResult(id,token,expiry);}

    @Transactional public void dispatch(StaffPrincipal actor,UUID id,String evidence,boolean manual){require(actor,"quote:issue");var row=lockAny(actor,id);if(!"ISSUED".equals(row.state()))throw conflict("STATE_CONFLICT","Only an issued quote can be dispatched.");String state=manual?"MANUAL_CONFIRMED":"ACCEPTED";int changed=jdbc.update("UPDATE takura.quote_revision SET dispatch_state=? WHERE id=? AND dispatch_state NOT IN ('ACCEPTED','MANUAL_CONFIRMED')",state,id);if(changed==0)return;jdbc.update("UPDATE takura.enquiry SET quote_dispatch_evidence=?,state=CASE WHEN state='QUOTE_IN_PREPARATION' THEN 'QUOTE_SENT' ELSE state END,revision=revision+1 WHERE id=?",required(evidence,500),row.enquiry());audit(actor,row.enquiry(),manual?"QUOTE_MANUAL_DISPATCH":"QUOTE_PROVIDER_ACCEPTED",Map.of("quote_revision_id",id));}
    @Transactional public QuoteView cancel(StaffPrincipal actor,UUID id,long expected,String reason){require(actor,"quote:draft");var row=lock(actor,id,expected);if(!Set.of("DRAFT","AWAITING_APPROVAL","APPROVED").contains(row.state()))throw conflict("STATE_CONFLICT","Only an unissued revision can be cancelled.");jdbc.update("UPDATE takura.quote_revision SET state='CANCELLED',approval_digest=NULL,approved_by=NULL,approved_at=NULL,revision=revision+1 WHERE id=?",id);audit(actor,row.enquiry(),"QUOTE_CANCELLED",Map.of("quote_revision_id",id,"reason_recorded",required(reason,500)!=null));return get(actor,id);}
    @Transactional public void revoke(StaffPrincipal actor,UUID id,String reason){require(actor,"quote:revoke");var row=lockAny(actor,id);if(!"ISSUED".equals(row.state()))throw conflict("STATE_CONFLICT","Only an issued revision can be revoked.");jdbc.update("UPDATE takura.quote_revision SET state='REVOKED',revoked_by=?,revoked_at=?,revocation_reason=?,revision=revision+1 WHERE id=?",actor.identityId(),now(),required(reason,500),id);jdbc.update("UPDATE takura.customer_quote_grant SET state='REVOKED',revoked_at=? WHERE quote_revision_id=?",now(),id);jdbc.update("UPDATE takura.quote_access_session SET revoked_at=? WHERE grant_id IN (SELECT id FROM takura.customer_quote_grant WHERE quote_revision_id=?)",now(),id);audit(actor,row.enquiry(),"QUOTE_REVOKED",Map.of("quote_revision_id",id));}
    @Transactional public void outcome(StaffPrincipal actor,UUID id,Outcome request){var row=lockAny(actor,id);if(!Set.of("ACCEPTED_EXTERNALLY","DECLINED","NO_RESPONSE").contains(request.outcome()))throw bad("OUTCOME_INVALID","Choose an offline quote outcome.");if("ACCEPTED_EXTERNALLY".equals(request.outcome()))require(actor,"commercial:confirm");else require(actor,"quote:draft");jdbc.update("INSERT INTO takura.quote_outcome(id,quote_revision_id,outcome,evidence_reference,effective_at,actor_identity_id,recorded_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(quote_revision_id,outcome) DO NOTHING",UUID.randomUUID(),id,request.outcome(),required(request.evidenceReference(),500),Timestamp.from(request.effectiveAt()),actor.identityId(),now());if("ACCEPTED_EXTERNALLY".equals(request.outcome()))jdbc.update("UPDATE takura.enquiry SET commercial_confirmation_evidence=?,state=CASE WHEN state='QUOTE_SENT' THEN 'WON' ELSE state END,revision=revision+1 WHERE id=?",id+":"+request.evidenceReference(),row.enquiry());audit(actor,row.enquiry(),"QUOTE_OUTCOME_"+request.outcome(),Map.of("quote_revision_id",id));}

    public List<QuoteView> list(StaffPrincipal actor,UUID enquiry){scope(actor,enquiry);return jdbc.query("SELECT r.id FROM takura.quote_revision r JOIN takura.quote_group g ON g.id=r.quote_group_id WHERE g.enquiry_id=? ORDER BY g.created_at DESC,r.revision_number DESC",(rs,n)->get(actor,(UUID)rs.getObject(1)),enquiry);}
    public QuoteView get(StaffPrincipal actor,UUID id){var row=lockAny(actor,id);return jdbc.queryForObject("SELECT r.id,g.id,g.enquiry_id,g.quote_number,r.revision_number,r.state,r.amount::text,r.currency,r.tax_mode,r.scope_summary,r.expires_at,r.dispatch_state,r.revision,r.pdf_attachment_id,r.pdf_checksum_sha256,r.approved_by,r.issued_at FROM takura.quote_revision r JOIN takura.quote_group g ON g.id=r.quote_group_id WHERE r.id=?",(rs,n)->new QuoteView((UUID)rs.getObject(1),(UUID)rs.getObject(2),(UUID)rs.getObject(3),rs.getString(4),rs.getInt(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getString(9),rs.getString(10),rs.getTimestamp(11).toInstant(),rs.getString(12),rs.getLong(13),(UUID)rs.getObject(14),rs.getString(15),(UUID)rs.getObject(16),rs.getTimestamp(17)==null?null:rs.getTimestamp(17).toInstant()),id);}

    @Transactional public Exchange exchange(String token,String risk){String riskHash=sha(risk==null?"unknown":risk);Instant cutoff=clock.instant().minusSeconds(600);jdbc.update("DELETE FROM takura.quote_access_attempt WHERE attempted_at<?",Timestamp.from(cutoff));Integer attempts=jdbc.queryForObject("SELECT count(*) FROM takura.quote_access_attempt WHERE risk_hash=? AND attempted_at>=?",Integer.class,riskHash,Timestamp.from(cutoff));if(attempts!=null&&attempts>=10)throw invalidToken();jdbc.update("INSERT INTO takura.quote_access_attempt(risk_hash,attempted_at) VALUES(?,?)",riskHash,now());if(token==null)throw invalidToken();var grants=jdbc.query("SELECT g.id,g.expires_at,r.id FROM takura.customer_quote_grant g JOIN takura.quote_revision r ON r.id=g.quote_revision_id WHERE g.token_hash=? AND g.state='ACTIVE' AND g.expires_at>? AND r.state='ISSUED'",(rs,n)->new Object[]{rs.getObject(1),rs.getTimestamp(2).toInstant(),rs.getObject(3)},sha(token),now());if(grants.isEmpty())throw invalidToken();String session=token();byte[] entropy=new byte[32];random.nextBytes(entropy);session=Base64.getUrlEncoder().withoutPadding().encodeToString(entropy);Instant expiry=clock.instant().plus(Duration.ofMinutes(20));Instant grantExpiry=(Instant)grants.getFirst()[1];if(expiry.isAfter(grantExpiry))expiry=grantExpiry;jdbc.update("INSERT INTO takura.quote_access_session(id,grant_id,session_hash,expires_at,created_at) VALUES(?,?,?,?,?)",UUID.randomUUID(),grants.getFirst()[0],sha(session),Timestamp.from(expiry),now());return new Exchange(session,expiry);}
    public CustomerView customer(String session){var access=access(session);return jdbc.queryForObject("SELECT g.quote_number,r.revision_number,r.state,r.amount::text,r.currency,r.tax_mode,r.scope_summary,r.expires_at FROM takura.quote_revision r JOIN takura.quote_group g ON g.id=r.quote_group_id WHERE r.id=?",(rs,n)->new CustomerView(rs.getString(1),rs.getInt(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getTimestamp(8).toInstant()),access.revision());}
    public Document document(String session){var access=access(session);var row=jdbc.queryForMap("SELECT a.private_key,a.private_version,a.expected_bytes,g.quote_number,r.revision_number FROM takura.quote_revision r JOIN takura.quote_group g ON g.id=r.quote_group_id JOIN takura.attachment a ON a.id=r.pdf_attachment_id WHERE r.id=?",access.revision());byte[] bytes=storage.readPrivate((String)row.get("private_key"),(String)row.get("private_version"));if(bytes.length>20*1024*1024)throw conflict("DOCUMENT_TOO_LARGE","The quote document exceeds the streaming limit.");return new Document(bytes,row.get("quote_number")+"-R"+row.get("revision_number")+".pdf");}

    private Access access(String session){if(session==null)throw invalidToken();var rows=jdbc.query("SELECT r.id FROM takura.quote_access_session s JOIN takura.customer_quote_grant g ON g.id=s.grant_id JOIN takura.quote_revision r ON r.id=g.quote_revision_id WHERE s.session_hash=? AND s.revoked_at IS NULL AND s.expires_at>? AND g.state='ACTIVE' AND g.expires_at>? AND r.state='ISSUED'",(rs,n)->new Access((UUID)rs.getObject(1)),sha(session),now(),now());if(rows.isEmpty())throw invalidToken();return rows.getFirst();}
    private Pdf pdf(StaffPrincipal actor,UUID id,UUID enquiry){var rows=jdbc.query("SELECT a.private_version,a.verified_checksum_sha256 FROM takura.attachment a JOIN takura.upload_session s ON s.id=a.upload_session_id WHERE a.id=? AND a.state='CLEAN' AND a.declared_content_type='application/pdf' AND a.private_version IS NOT NULL AND ((s.purpose='STAFF_MEDIA' AND s.owner_identity_id=?) OR a.enquiry_id=?)",(rs,n)->new Pdf(rs.getString(1),rs.getString(2)),id,actor.identityId(),enquiry);if(rows.isEmpty())throw conflict("CLEAN_PDF_REQUIRED","Select an authorised CLEAN scanned PDF.");return rows.getFirst();}
    private void validateDraft(CreateDraft r){if(r==null||r.pdfAttachmentId()==null||r.amount()==null||r.amount().scale()>2||r.amount().signum()<0)throw bad("QUOTE_INVALID","PDF and exact non-negative amount are required.");if(!Set.of("NOT_APPLICABLE","INCLUSIVE","EXCLUSIVE","UNCONFIRMED").contains(r.taxMode()))throw bad("TAX_MODE_INVALID","Choose a supported tax mode.");if(!upper(r.currency()).matches("[A-Z]{3}"))throw bad("CURRENCY_INVALID","Currency must be ISO-style three letters.");required(r.scopeSummary(),5000);if(r.materialSnapshot()==null||r.materialSnapshot().isEmpty()||r.commercialTerms()==null||r.commercialTerms().isEmpty())throw bad("QUOTE_METADATA_REQUIRED","Material basis and commercial terms are required.");}
    private void ensureComplete(UUID id){var m=jdbc.queryForMap("SELECT a.state,a.verified_checksum_sha256=r.pdf_checksum_sha256 AS checksum_ok,r.review_checklist->>'pdf_amount_matches' AS amount_ok,r.review_checklist->>'terms_reviewed' AS terms_ok FROM takura.quote_revision r JOIN takura.attachment a ON a.id=r.pdf_attachment_id WHERE r.id=?",id);if(!"CLEAN".equals(m.get("state"))||!Boolean.TRUE.equals(m.get("checksum_ok"))||!"true".equals(m.get("amount_ok"))||!"true".equals(m.get("terms_ok")))throw conflict("QUOTE_REVIEW_INCOMPLETE","Clean matching PDF and completed review checklist are required.");}
    private Row lock(StaffPrincipal actor,UUID id,long expected){var row=lockAny(actor,id,true);if(row.revision()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"STALE_REVISION");return row;}
    private Row lockAny(StaffPrincipal actor,UUID id){return lockAny(actor,id,false);}private Row lockAny(StaffPrincipal actor,UUID id,boolean lock){String suffix=lock?" FOR UPDATE":"";var rows=jdbc.query("SELECT r.state,r.revision,r.created_by,g.enquiry_id,g.id FROM takura.quote_revision r JOIN takura.quote_group g ON g.id=r.quote_group_id WHERE r.id=?"+suffix,(rs,n)->new Row(rs.getString(1),rs.getLong(2),(UUID)rs.getObject(3),(UUID)rs.getObject(4),(UUID)rs.getObject(5)),id);if(rows.isEmpty())throw notFound();scope(actor,rows.getFirst().enquiry());return rows.getFirst();}
    private void scope(StaffPrincipal p,UUID enquiry){if(!(p.may("enquiry:all:read")||p.may("enquiry:assigned:read")||p.may("record:granted:read")))throw notFound();String teams=p.teams().stream().filter(Set.of("PROPERTY","CABINETRY","BOARDS","GENERAL")::contains).map(t->"'"+t+"'").reduce((a,b)->a+","+b).orElse("");String sql=p.may("enquiry:all:read")?"TRUE":"(("+(teams.isEmpty()?"FALSE":"e.team_code IN ("+teams+") AND (e.owner_identity_id IS NULL OR e.owner_identity_id=?)")+") OR EXISTS(SELECT 1 FROM takura.enquiry_record_grant x WHERE x.enquiry_id=e.id AND x.staff_identity_id=?))";Integer n=p.may("enquiry:all:read")?jdbc.queryForObject("SELECT count(*) FROM takura.enquiry e WHERE e.id=? AND "+sql,Integer.class,enquiry):jdbc.queryForObject("SELECT count(*) FROM takura.enquiry e WHERE e.id=? AND "+sql,Integer.class,enquiry,p.identityId(),p.identityId());if(n==null||n!=1)throw notFound();}
    private String nextNumber(){jdbc.query("SELECT pg_advisory_xact_lock(hashtext('quote-number'))",rs->{rs.next();return null;});Integer n=jdbc.queryForObject("SELECT count(*)+1 FROM takura.quote_group WHERE extract(year from created_at)=?",Integer.class,clock.instant().atZone(zone).getYear());return "Q-"+clock.instant().atZone(zone).getYear()+"-"+String.format("%06d",n);}
    private String digest(String checksum,CreateDraft r){return sha(checksum+"|"+r.amount().toPlainString()+"|"+upper(r.currency())+"|"+r.taxMode()+"|"+required(r.scopeSummary(),5000)+"|"+write(r.materialSnapshot())+"|"+write(r.commercialTerms())+"|"+write(r.reviewChecklist()));}
    private String write(Object value){try{return json.copy().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsString(value);}catch(Exception e){throw bad("JSON_INVALID","Structured quote metadata is invalid.");}}
    private void audit(StaffPrincipal p,UUID enquiry,String action,Map<String,Object> metadata){jdbc.update("INSERT INTO takura.operational_audit(id,actor_identity_id,target_type,target_id,action,outcome,metadata,occurred_at) VALUES(?,?,'ENQUIRY',?,?, 'SUCCESS',?::jsonb,?)",UUID.randomUUID(),p.identityId(),enquiry,action,write(metadata),now());}
    private IssueResult issueResult(UUID id,String token,Instant expiry){return new IssueResult(id,token==null?null:"/quote/view#"+token,expiry);}
    private Timestamp now(){return Timestamp.from(clock.instant());}private boolean exists(String sql,Object...args){return Boolean.TRUE.equals(jdbc.queryForObject(sql,Boolean.class,args));}private void require(StaffPrincipal p,String op){permissions.require(p,op);}private static String upper(String v){return v==null?"":v.toUpperCase(Locale.ROOT);}private static String required(String v,int max){if(v==null||v.isBlank()||v.length()>max)throw bad("FIELD_REQUIRED","A required quote field is missing or too long.");return v.trim();}
    private String token(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private static String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static ResponseStatusException bad(String c,String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,c+": "+m);}private static ResponseStatusException conflict(String c,String m){return new ResponseStatusException(HttpStatus.CONFLICT,c+": "+m);}private static ResponseStatusException notFound(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"QUOTE_NOT_FOUND");}private static ResponseStatusException invalidToken(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"QUOTE_ACCESS_INVALID");}
    private record Pdf(String version,String checksum){}private record Row(String state,long revision,UUID createdBy,UUID enquiry,UUID group){}private record Access(UUID revision){}
    public record CreateDraft(UUID groupId,UUID pdfAttachmentId,BigDecimal amount,String currency,String taxMode,String scopeSummary,Map<String,Object> materialSnapshot,Map<String,Object> commercialTerms,Map<String,Object> reviewChecklist){}
    public record QuoteView(UUID id,UUID groupId,UUID enquiryId,String quoteNumber,int revisionNumber,String state,String amount,String currency,String taxMode,String scopeSummary,Instant expiresAt,String dispatchState,long revision,UUID pdfAttachmentId,String pdfChecksum,UUID approvedBy,Instant issuedAt){}
    public record IssueResult(UUID quoteRevisionId,String customerUrl,Instant expiresAt){}public record Exchange(String session,Instant expiresAt){}public record CustomerView(String quoteNumber,int revisionNumber,String state,String amount,String currency,String taxMode,String scopeSummary,Instant expiresAt){}public record Document(byte[] bytes,String filename){}public record Outcome(String outcome,String evidenceReference,Instant effectiveAt){}
}
